import { Schema } from "effect";

/** What ReadFile takes. */
const ReadFileRequest = Schema.Struct({
	/**
	 * The file to read, such as "hello.txt". Only its base name is used, so a
	 * request never leaves the files directory.
	 */
	name: Schema.String.check(
		Schema.isMinCodePoints(5, {
			message: "Must be at least 5 characters long",
		}),
		Schema.isMaxCodePoints(25, {
			message: "Must be at most 25 characters long",
		}),
	),
});
interface ReadFileRequest extends Schema.Schema.Type<typeof ReadFileRequest> {}

/** What ReadFile succeeds with. */
const ReadFileSuccess = Schema.Struct({
	/** The whole file, decoded as UTF-8. */
	contents: Schema.String,
});
interface ReadFileSuccess extends Schema.Schema.Type<typeof ReadFileSuccess> {}

export class NotTxtFile extends Schema.TaggedError<NotTxtFile>()("NotTxtFile", {
	/** The requested name, which does not end in .txt. */
	file: Schema.String,
}) {
	override get message(): string {
		return `"${this.file}" is not a .txt file`;
	}
}

export class FileNotFound extends Schema.TaggedError<FileNotFound>()(
	"FileNotFound",
	{
		/** The requested name; no such .txt file exists. */
		file: Schema.String,
	},
) {
	override get message(): string {
		return `"${this.file}" does not exist`;
	}
}

/** Every error ReadFile can fail with. */
const ReadFileError = Schema.Union([NotTxtFile, FileNotFound]);
type ReadFileError = typeof ReadFileError.Type;

// Declared under their full names and exported under short ones, so
// hovers say ReadFileSuccess rather than Success.
export {
	ReadFileError as Error,
	ReadFileRequest as Request,
	ReadFileSuccess as Success,
};
